<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,watch,nextTick} from 'vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
import type {CutLine,CutScope,Command} from '../../../packages/schema/index';
const props=defineProps<{sectionActive?:boolean;language:'zh'|'en';targetId?:string}>(),emit=defineEmits<{draw:[request:{kind:'pen'|'freehand'|'brush'|'lasso'|'section';lineId?:string}];focus:[lineId:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh'),mesh=computed(()=>store.data.project?.surface);
const advanced=inject('advancedMode',ref(false));
const search=ref(''),selected=ref(''),draft=ref<CutLine>(),sectionOpen=ref(false),sectionElement=ref<HTMLElement>(),sectionAxis=ref<'x'|'y'|'z'>('y'),sectionMm=ref(0),sectionName=ref('截面裁剪线'),sectionRegions=ref<string[]>([]);
const scope=ref<CutScope>({side:'full',axis:'x',positionMm:0,closeMidline:true}),regions=computed(()=>[...new Set(mesh.value?.faces.map(f=>f.region)??[])]);
const panel=ref<HTMLElement>();
const history=useDraftHistory(()=>({draft:draft.value,scope:scope.value,sectionAxis:sectionAxis.value,sectionMm:sectionMm.value,sectionName:sectionName.value,sectionRegions:sectionRegions.value}),value=>{draft.value=value.draft;scope.value=value.scope;sectionAxis.value=value.sectionAxis;sectionMm.value=value.sectionMm;sectionName.value=value.sectionName;sectionRegions.value=value.sectionRegions;},()=>!props.sectionActive&&!!panel.value?.getClientRects().length,()=>store.busy);
const lines=computed(()=>mesh.value?.cutLines?.filter(l=>l.name.toLowerCase().includes(search.value.toLowerCase()))??[]),midlines=computed(()=>mesh.value?.cutLines?.filter(l=>l.kind==='midline')??[]);
watch(()=>JSON.stringify(mesh.value?.cutScope),()=>{const s=mesh.value?.cutScope;history.reset(()=>{scope.value=structuredClone(s??{side:'full',axis:'x',positionMm:0,closeMidline:true});});},{immediate:true});
watch(()=>mesh.value?.id,()=>{history.reset(()=>{selected.value='';draft.value=undefined;sectionMm.value=mesh.value?mesh.value.vertices.reduce((s,v)=>s+v.yMm,0)/mesh.value.vertices.length:0;sectionRegions.value=[];});});
watch(()=>JSON.stringify(mesh.value?.cutLines),()=>{history.reset(()=>{if(selected.value){const line=mesh.value?.cutLines?.find(l=>l.id===selected.value);draft.value=line?JSON.parse(JSON.stringify(line)):undefined;}});},{deep:false});
function choose(line:CutLine){const base=line.mirroredFrom?mesh.value?.cutLines?.find(l=>l.id===line.mirroredFrom)??line:line;history.reset(()=>{selected.value=base.id;draft.value=JSON.parse(JSON.stringify(base));});emit('focus',line.id);}
watch(()=>props.targetId,id=>{if(id?.startsWith('cutLine:')){const line=mesh.value?.cutLines?.find(l=>l.id===id.slice(8));if(line)choose(line);}},{immediate:true});
async function apply(command:Command){const p=store.data.project;if(p)return store.run(()=>window.fpcad.apply(p.id,p.revision,JSON.parse(JSON.stringify(command))));}
async function metadata(line:CutLine,enabled=line.enabled,name=line.name){await apply({type:'surface.cutLine.meta',lineId:line.id,name,enabled});}
async function remove(line:CutLine){if(await apply({type:'surface.cutLine.delete',lineId:line.id})){selected.value='';draft.value=undefined;}}
async function savePath(){const d=draft.value;if(!d)return;if(d.section)await apply({type:'surface.section',id:d.id,name:d.name,section:d.section});else if(d.projection)await apply({type:'surface.curve',id:d.id,name:d.name,kind:d.kind as 'pen'|'freehand',regions:d.regions,controlPoints:d.controlPoints,projection:d.projection,tension:d.tension,closed:d.closed,symmetric:d.symmetric});}
function insert(index:number){const d=draft.value;if(!d||index>=d.controlPoints.length-1)return;const a=d.controlPoints[index],b=d.controlPoints[index+1];d.controlPoints.splice(index+1,0,{id:crypto.randomUUID(),xMm:(a.xMm+b.xMm)/2,yMm:(a.yMm+b.yMm)/2,zMm:(a.zMm+b.zMm)/2});}
async function section(){await apply({type:'surface.section',name:sectionName.value,section:{axis:sectionAxis.value,positionMm:sectionMm.value,...(sectionRegions.value.length?{regions:sectionRegions.value}:{})}});}
async function openSection(){if(props.sectionActive)return;sectionOpen.value=true;await nextTick();sectionElement.value?.scrollIntoView({block:'nearest'});sectionElement.value?.querySelector<HTMLInputElement>('input[type=number]')?.focus();}
watch(()=>props.sectionActive,active=>{if(active)sectionOpen.value=false;});
defineExpose({openSection});
function restore(){window.dispatchEvent(new CustomEvent('fpcad-document-history',{detail:{redo:false}}));}
</script>
<template><section v-if="mesh" ref="panel" class="surface-cut-panel"><div class="saved-cut-header"><strong>{{zh?'裁剪线工具':localize('Cut line tools')}}</strong><button :disabled="store.busy||(!store.data.canUndo&&!history.canUndo.value)" @click="restore">{{zh?'恢复':localize('Restore')}}</button></div><div class="two-col cut-drawing-primary"><button :disabled="store.busy" @click="emit('draw',{kind:'pen'})">{{zh?'曲面钢笔':localize('Surface pen')}}</button><button :disabled="store.busy" @click="emit('draw',{kind:'freehand'})">{{zh?'自由绘制':localize('Free draw')}}</button></div><div class="two-col"><button :disabled="store.busy" @click="emit('draw',{kind:'brush'})">{{zh?'裁切画笔':localize('Cut brush')}}</button><button :disabled="store.busy" @click="emit('draw',{kind:'lasso'})">{{zh?'裁切套索':localize('Cut lasso')}}</button></div><button class="section-workspace-button" :disabled="store.busy" @click="emit('draw',{kind:'section'})">{{zh?'在模型上调整截面':localize('Adjust section on model')}}</button><details v-show="!sectionActive" class="legacy-section-generator" ref="sectionElement" :open="sectionOpen" @toggle="sectionOpen=($event.target as HTMLDetailsElement).open"><summary>{{zh?'截面环线':localize('Section ring')}}</summary><label>{{zh?'截面名称':localize('Section name')}}<input v-model="sectionName" maxlength="120"></label><div class="two-col"><label>{{zh?'截面轴':localize('Axis')}}<select v-model="sectionAxis"><option>x</option><option>y</option><option>z</option></select></label><label>{{zh?'截面位置 mm':localize('Position mm')}}<input v-model.number="sectionMm" type="number" step="1"></label></div><label>{{zh?'绘制部件（不选表示全部）':localize('Parts (empty = all)')}}</label><div class="section-parts"><label v-for="r in regions" :key="r"><input v-model="sectionRegions" type="checkbox" :value="r">{{r}}</label></div><button :disabled="store.busy||!sectionName.trim()||!Number.isFinite(sectionMm)" @click="section">{{zh?'生成并保存截面环线':localize('Create section ring')}}</button></details><details v-if="advanced" class="half-cut-settings"><summary>{{zh?'半侧制版与中线围合':localize('Half-side & midline')}}</summary><label>{{zh?'制版范围':localize('Cutting scope')}}<select v-model="scope.side" :aria-label="zh?'制版范围':localize('Cutting scope')"><option value="full">{{zh?'完整模型':localize('Full model')}}</option><option value="right">{{zh?'半侧 · 右侧':localize('Half · right')}}</option><option value="left">{{zh?'半侧 · 左侧':localize('Half · left')}}</option></select></label><div class="two-col"><label>{{zh?'中线轴':localize('Midline axis')}}<select v-model="scope.axis"><option>x</option><option>y</option><option>z</option></select></label><label>{{zh?'中线位置 mm':localize('Midline mm')}}<input v-model.number="scope.positionMm" type="number" step="1"></label></div><label class="check-label"><input v-model="scope.closeMidline" type="checkbox">{{zh?'中线参与围合（缝合）；关闭则沿中线对折裁剪':localize('Sewn midline; unchecked means cut on fold')}}</label><button :disabled="store.busy||!Number.isFinite(scope.positionMm)" @click="apply({type:'surface.cutScope',scope})">{{zh?'应用制版范围':localize('Apply scope')}}</button><small>{{zh?'右侧为坐标大于中线的一侧，左侧为小于中线的一侧。半侧纸样自动设置镜像双片；对折边缝份为 0 mm。':localize('Right uses coordinates above the midline; left below. Half patterns use mirrored pairs, fold edges have zero allowance.')}}</small><div v-if="midlines.length" class="midline-list"><strong>{{zh?'中线边界管理':localize('Midline boundaries')}}</strong> · {{midlines.length}}<button v-for="line in midlines" :key="line.id" @click="choose(line)">{{line.name}} · {{line.edges.length}} {{zh?'段':localize('edges')}}</button></div></details><input v-model="search" :placeholder="zh?'搜索裁剪线':localize('Search cut lines')" :aria-label="zh?'搜索裁剪线':localize('Search cut lines')"><div class="saved-cut-list"><div v-for="line in lines" :key="line.id" :class="['saved-line',{active:selected===line.id||selected===line.mirroredFrom}]"><input type="checkbox" :checked="line.enabled" :disabled="store.busy||!!line.mirroredFrom" :aria-label="(zh?'启用裁剪线 ':localize('Enable cut '))+line.name" @change="metadata(line,($event.target as HTMLInputElement).checked)"><button class="select-cut" @click="choose(line)"><strong>{{line.name}}</strong><small>{{line.edges.length}} {{zh?'段 · 已保存':localize('edges · saved')}}{{line.mirroredFrom?(zh?' · 对称':localize(' · symmetric')):''}}</small></button><button :aria-label="(zh?'聚焦裁剪线 ':localize('Focus cut '))+line.name" @click="emit('focus',line.id)">⌖</button></div><small v-if="!lines.length">{{zh?'保存绘制后，裁剪线会显示在这里。':localize('Save a drawing to list it here.')}}</small></div><div v-if="draft&&!sectionActive" class="cut-line-editor"><label>{{zh?'裁剪线名称':localize('Cut line name')}}<input v-model="draft.name" maxlength="120" @change="metadata(draft,draft.enabled,draft.name)"></label><div class="two-col"><button :disabled="store.busy||draft.kind==='midline'" @click="emit('draw',{kind:draft.section?'section':draft.kind as 'pen'|'freehand',lineId:draft.id})">{{draft.section?(zh?'在模型上调整截面':localize('Adjust section on model')):(zh?'编辑路径节点':localize('Edit path nodes'))}}</button><button :disabled="store.busy||draft.kind==='midline'&&mesh.cutScope?.side!=='full'" @click="remove(draft)">{{zh?'删除裁剪线':localize('Delete cut line')}}</button></div><small>{{zh?'在模型上选择并拖动路径圆点；选中点后插入或删除，保存前可取消。':localize('Select and drag visible path nodes on the model. Insert or delete the selected node, then save or cancel.')}}</small><template v-if="draft.kind!=='midline'"><template v-if="draft.section"><label>{{zh?'截面位置 mm':localize('Section position mm')}}<input v-model.number="draft.section.positionMm" type="number" step="1"></label></template><template v-else><label class="check-label"><input v-model="draft.symmetric" type="checkbox">{{zh?'对称绘制':localize('Symmetric drawing')}}</label><label v-if="advanced" class="check-label"><input v-model="draft.closed" type="checkbox">{{zh?'闭合裁剪线':localize('Close cut line')}}</label><label v-if="advanced&&draft.kind==='pen'">{{zh?'钢笔张力':localize('Pen tension')}}<input v-model.number="draft.tension" type="range" min="0" max="1" step=".05"></label><details v-if="advanced"><summary>{{zh?'路径点调整与新增切分点':localize('Path points & insert points')}} · {{draft.controlPoints.length}}</summary><div v-for="(p,i) in draft.controlPoints" :key="p.id" class="cut-control-point"><span>{{i+1}}</span><label v-for="axis in (['xMm','yMm','zMm'] as const)" :key="axis">{{axis[0].toUpperCase()}} mm<input v-model.number="p[axis]" type="number" step=".5"></label><button :disabled="draft.controlPoints.length<=2" :aria-label="'Remove point '+(i+1)" @click="draft.controlPoints.splice(i,1)">−</button><button v-if="i<draft.controlPoints.length-1" :disabled="draft.controlPoints.length>=400" :aria-label="'Insert point after '+(i+1)" @click="insert(i)">＋</button></div></details></template><button :disabled="store.busy||!draft.name.trim()" @click="savePath">{{zh?'应用路径调整':localize('Apply path edits')}}</button></template></div></section></template>
<style scoped>.surface-cut-panel{padding:15px;border-bottom:1px solid var(--border);font-size:11px}.saved-cut-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.surface-cut-panel label{font-size:11px;margin:10px 0}.surface-cut-panel summary{font-size:12px;cursor:pointer}.surface-cut-panel details{margin:12px 0;padding:8px 0;border-block:1px solid var(--border)}.surface-cut-panel small{display:block;color:var(--text-muted);line-height:1.7;margin:6px 0}.section-parts{display:grid;grid-template-columns:1fr 1fr;max-height:150px;overflow:auto;gap:4px}.section-parts label{display:flex;gap:4px;align-items:center;margin:2px;min-width:0;overflow-wrap:anywhere}.section-parts input,.saved-line>input{width:auto}.saved-cut-list{max-height:240px;overflow:auto;margin-top:8px}.saved-line{display:flex;align-items:center;gap:5px;border:1px solid transparent;border-radius:4px}.saved-line.active{border-color:var(--accent)}.select-cut{flex:1;text-align:left;min-width:0;background:transparent}.select-cut strong{display:block;overflow-wrap:anywhere}.select-cut small{font-size:10px;margin:3px 0}.cut-line-editor{margin-top:12px}.cut-control-point{display:grid;grid-template-columns:14px repeat(3,minmax(0,1fr)) 22px 22px;gap:3px;align-items:center}.cut-control-point input{padding:6px 2px;font-size:10px;min-width:0}.cut-control-point button{padding:3px}.midline-list>button{display:block;width:100%;margin:4px 0;text-align:left}</style>

<style scoped>.cut-drawing-primary{margin-bottom:8px}.section-workspace-button{display:block;width:100%;margin-top:8px}</style>

